<script setup lang="ts">
import { ref,onMounted } from 'vue';import { useRouter } from 'vue-router';import { state,setTheme,run,logout,call } from '../store';import { storage } from '../storage/db';import { exportJson } from '../storage/export';
const router=useRouter(),current=ref(''),password=ref(''),confirmation=ref(''),busy=ref(false),backups=ref<any[]>([]);
onMounted(async()=>{if(state.auth)backups.value=await storage.backups(state.auth.profile.id)});
async function leave(){if(!confirm('تسجيل الخروج؟ العمل غير المرسل لا يبقى بعد إغلاق الصفحة أو تحديثها.'))return;await run(async()=>{await logout();await router.replace('/login')})}
async function changePassword(){busy.value=true;await run(async()=>{try{await call('/profile/password','PUT',{current_password:current.value,password:password.value,password_confirmation:confirmation.value});await logout();await router.replace('/login');state.message='تم تغيير كلمة المرور. سجّل الدخول مجددًا.'}finally{current.value='';password.value='';confirmation.value=''}});busy.value=false}
</script>
<template><section class="narrow"><h1>حسابي</h1><div class="card profile-card"><div class="profile-avatar">{{state.auth?.profile.name.slice(0,1)}}</div><h2>{{state.auth?.profile.name}}</h2><p dir="ltr" class="muted">{{state.auth?.profile.email}}</p></div><div class="card"><label class="between">الوضع الداكن<input type="checkbox" :checked="state.theme==='dark'" role="switch" @change="run(()=>setTheme(($event.target as HTMLInputElement).checked?'dark':'light'))"></label></div><details class="card"><summary>تغيير كلمة المرور</summary><form class="form" @submit.prevent="changePassword"><label>كلمة المرور الحالية<input v-model="current" type="password" autocomplete="current-password" required></label><label>كلمة المرور الجديدة<input v-model="password" type="password" autocomplete="new-password" minlength="8" required></label><label>تأكيد كلمة المرور<input v-model="confirmation" type="password" autocomplete="new-password" required></label><button class="primary" :disabled="!state.online||busy">حفظ كلمة المرور</button><small class="muted">تغيير كلمة المرور يحتاج اتصالًا، ويطلب تسجيل الدخول مجددًا.</small></form></details><details v-if="backups.length" class="card"><summary>نسخ استرجاع مؤقتة ({{backups.length}})</summary><div v-for="backup in backups" :key="backup.id" class="between backup-row"><span>{{new Date(backup.createdAt).toLocaleString('ar')}}</span><button class="quiet" @click="exportJson('halaka-recovery.json',backup.draft)">تنزيل</button></div></details><p class="muted">يبقى فقط الملف الشخصي ورمز الدخول محفوظين. أرسل الحصة قبل تحديث الصفحة أو إغلاقها.</p><button class="quiet danger full" @click="leave">تسجيل الخروج</button></section></template>
